4,4,77,332,"「あたしとのデート大作戦、またの名をクリスマス遊園地の旅、まもなく始まりまーす！　えへへ、まずは最初のミッション、あたしの手作りチョコクッキー、美味しそうに食べられるかなのコーナー！　はい、あ～ん♪」",200066,2,"deco/character/sigongdongshi_SD",false,false,false,false,false,false,false,"1",false,false,"-100,0,1","80,-80,1",false,"-100,0,1","-100,0,1",false,false,false,false,false,false,false,false,false,false,false,2110,917,388,936,418,2104,2754,936,610,2104,1261,"sigongdongshi_sd"},h)g[406605]=b({e[46057],406605,15,122,333,"「すぅ……はぁ……。この歌は、普通の子な私に、私が持つ特別さに気付かせてくれた人のために、ありったけの想いを込めて書きました。だから……私の気持ち、聴いてください。じゃあ、行くよー！　3、2、1――！」",200066,2,"deco/character/sigongdongshi_OX",false,false,false,false,false,false,false,"1",false,false,"-60,0,1","240,-140,0.94","-100,0,1","-100,0,1","-110,0,1",false,false,false,false,false,false,false,false,false,false,false,2023,891,388,374,238,3026,3071,436,584,2902,1261,"sigongdongshi_ox"},h)g[406606]=b({e[9057],406606,21,20,334,"「雀士さん、お疲れさま！\nはい、はちみつドリンク。疲れによく効くよ！\nあ……うん、これ、あたしがいつも使ってる水筒。おうちで作って、そのまま持ってきたから……。\n気にしないで、よかったらそのまま使って！\n……あ、あの。\n……頑張ってね！ 応援してます！」",200066,2,"deco/character/sigongdongshi_ydh","sigongdongshi_ydh"},h)g[406701]=b({e[35057],406701,false,148,335,false,200067,false,"deco/character/qingluan",302002,60,false,false,false,false,85,"1",false,false,false,false,false,false,false,"150,-20,1",false,"-30,100,1",false,"-30,100,1",false,"-10,60,1","0,60,1","-10,60,1","0,60,1","0,40,1","qingluan"},h)g[406702]=b({e[12057],406702,1,4,336,"「何れにせよ、青き鳥は雲の果てへ帰りゆくであろう。\nその時は、そなたも共に喜んでくれるか？」",200067,1,"deco/character/qingluan_0",302002,60,1,"qingluan_0"},h)g[406703]=b({e[24045],406703,6,72,337,"「律回り歳晩れて氷霜少なし、春人間に到らば草木知る……そなた、このセイランと共に、庭歩きに興じてくれぬか？」",200067,2,"deco/character/406703",false,false,1,false,false,false,false,"1",false,"140,0,0.98","0,0,0.98",false,"0,0,0.98","0,0,0.98","0,0,0.98",1,5520,5000,2974,4677,8000,8500,16000,8000,15000,8000,8000,"qingluan_cj",false,0},h)g[406704]=b({e[17045],406704,2,84,338,"「清冽なる水は身の穢れを祓うが、其の内の卑俗なる欲を洗い流すには至らぬ。\n……そなたが関心を抱いておるのなら、我は構わぬぞ。共に暑気を払うとしよう。」",200067,2,"deco/character/qingluan_xr"